"""The stylesheet behind the `extended` profile's colouring and tables.

`render_css()` is the one source: `./manage.py build_highlight_css` writes it to
`core/css/highlight.css` (committed, loaded by `core/base.html`) and a test fails while the
committed file differs. Pygments' `friendly` style for light, `github-dark` for dark, both scoped
to `pre.hl` and using the renderer's `hl-` class prefix.
"""

from pygments.formatters.html import HtmlFormatter

from .renderer import HIGHLIGHT_PREFIX

CSS_PATH = 'core/css/highlight.css'

_HEADER = (
    '/* Generated by `./manage.py build_highlight_css` from apps/core/markdown/highlight_css.py.\n'
    '   Do not edit by hand. */\n'
)

_TABLES = """.md-table {
  overflow-x: auto;
}
.md-table th,
.md-table td {
  padding: 0.375rem 0.75rem;
  border: 1px solid rgb(var(--c-gray-200));
}
.dark .md-table th,
.dark .md-table td {
  border-color: rgb(var(--c-gray-700));
}
"""


def _style(style: str, scope: str) -> str:
    """Pygments' rules for `style`, only those that apply inside `scope`.

    It also writes a few unscoped rules (`pre { line-height }`, the line-number columns): they
    would change every `<pre>` on the site, so they are dropped.
    """
    rules = HtmlFormatter(style=style, classprefix=HIGHLIGHT_PREFIX).get_style_defs(scope)
    return '\n'.join(line for line in rules.splitlines() if line.startswith(scope))


def render_css() -> str:
    return (
        f'{_HEADER}\n/* Light: Pygments "friendly". */\n{_style("friendly", "pre.hl")}\n\n'
        f'/* Dark: Pygments "github-dark". */\n{_style("github-dark", ".dark pre.hl")}\n\n'
        f'/* Tables of the extended profile. */\n{_TABLES}'
    )
